'use strict';
const protectionLimit=AU?250000:120000;
const protectionSource=AU?'https://www.apra.gov.au/financial-claims-scheme-fcs':'https://www.fscs.org.uk/what-we-cover/banks-building-societies-credit-unions/deposit-limit/';
const customerJourney=[
 ['Connect what you own.','Your accounts, companies, shares, property and '+(AU?'super.':'pensions.')+' Upload statements and agreements. Ron proposes the records; your firm checks the details.','wealth','See the customer view'],
 ['Know what you can use.','Keep spending and tax reserves aside. Check contribution limits, available allowances and cash held above standard bank protection.','limits','Check limits & cash'],
 ['Say what you want to invest in.','Choose the amount, date and how long you expect to hold it. Compare where the money comes from, ownership, tax now and tax later.','invest/type','Try an investment'],
 ['Ask your adviser to check it.','Your firm reviews the plan and any missing information, speaks to you and releases its recommendation. A draft scenario is not approved advice.','client/alex','See what the adviser receives'],
 ['Approve the exact instructions.','Sign the approved version. Connected providers would sell, settle, reserve tax, transfer and invest in that order. Changes need fresh approval.','plans','See example plans'],
 ['Confirm. File. Done.','Your accountant prepares the returns. Answer the missing questions, confirm the final figures and approve the submission. Full drafts remain available.','filing','Try a filing checklist']
];
const firmJourney=[
 ['Invite the client.','Your firm can add clients directly. Record scope, permissions, risk profile and objectives. Connect accounts and verify who owns what.','adviser','Open the client list'],
 ['Review the exceptions.','The work queue brings together documents, client requests and filing questions. AI proposes fields and missing questions; your professionals verify them.','workqueue','Open the work queue'],
 ['Review a plan with the context.','The portfolio, funding routes and tax assumptions sit beside the client’s number and interaction history. Call them and record what you agreed.','client/alex','Open Alex’s portfolio'],
 ['Release the recommendation.','Approve or reject the proposal with reasons. Advice and tax adjustments need the firm’s review before the customer receives them as a recommendation.','client/alex','Review a client request'],
 ['Oversee authorised execution.','The customer signs a specific version. The proposed system checks permissions and funds, then waits for each provider’s confirmed result. Exceptions stop later steps.','plans','See the plan lifecycle'],
 ['Prepare the next submission.','Group work by deadline and legal owner. Pre-fill known figures, resolve missing answers, review the full draft and obtain the customer’s final approval.','filing','See filing preparation']
];
function journeySteps(items,role){return `<ol class="journey-steps">${items.map(([title,copy,route,label],i)=>`<li><span class="journey-index">${i+1}</span><div><h2>${title}</h2><p>${copy}</p><a href="#${route}" data-journey-role="${role}">${label} →</a></div></li>`).join('')}</ol>`}
function flowPage(role){const firm=role==='firm';return `<p class="eyebrow">How it would work · ${regionName}</p><h1>${firm?'The firm’s day.':'The customer’s journey.'}</h1><p class="journey-lead">${firm?'One queue. The client’s context beside the work. Your professionals make the decisions.':'See your money. Make a plan. Let the professionals check the details.'}</p><div class="journey-switch"><a href="#journey/customer" ${!firm?'aria-current="page"':''}>Customer</a><a href="#journey/firm" ${firm?'aria-current="page"':''}>Firm</a></div>${journeySteps(firm?firmJourney:customerJourney,firm?'firm':'customer')}<p class="fine">Proposed workflow, illustrated with fictional records. Connections, document AI, signatures, payments and submissions are simulated.</p><button class="primary wide" data-start-journey="${firm?'firm':'customer'}">Walk through it in the demo →</button>`}
tourHome=function(){return `<div class="tour-intro"><p class="eyebrow">Startup proposal · ${regionName}</p><h1>Meet ron.</h1><p>A place for hands-on investors to plan, and their advisers to check the work. Less chasing documents. More time with clients.</p><div class="tour-region"><a href="?region=uk#tour" ${!AU?'aria-current="page"':''}>United Kingdom</a><a href="?region=au#tour" ${AU?'aria-current="page"':''}>Australia</a></div><div class="journey-entry"><article><span class="eyebrow">For the customer</span><h2>Your money. Your decisions.</h2><p>Know what you own, what you can invest and what tax is coming. Ask your adviser to check a plan before you commit.</p><a class="primary action-link" href="#journey/customer">How the customer journey works →</a></article><article><span class="eyebrow">For the firm</span><h2>The context, without the chasing.</h2><p>Documents, portfolios, requests and filing in one queue. The client’s number and your notes alongside the work.</p><a class="primary action-link" href="#journey/firm">How the firm’s workflow works →</a></article></div><button class="secondary wide" id="start-tour">Take the full feature tour →</button><div class="tour-choices"><a href="#wealth" data-journey-role="customer">Explore the customer demo →</a><a href="#adviser" data-journey-role="firm">Explore the firm demo →</a><a href="/${region}/">Read the startup proposal ↗</a></div><p class="fine">Fictional clients and forecasts. No live advice, bank/broker API, AI document analysis, DocuSign or submission. Rules checked 17 October 2026; this is a demonstration for discussion.</p></div>`};window.ronScreens.tour=tourHome;
function protectionExample(){return `<section class="protection-example"><p class="eyebrow">Bank protection · interactive example</p><h2>${AU?'Too much in one bank?':'Cash above the standard limit?'}</h2><p>${AU?'CommBank and Bankwest share one Australian banking licence. Their eligible deposits are added together for each account holder.':'Two accounts with the same authorised bank share one standard deposit-protection limit for each eligible depositor.'}</p><p class="fine">These are editable example balances, separate from the portfolio records.</p><form id="protection-form"><fieldset><legend>Personal deposits · same account holder</legend><label>${AU?'CommBank':'Main account'}<input id="deposit-first" type="number" min="0" step="1000" value="${AU?280000:145000}" inputmode="decimal"></label><label>${AU?'Bankwest':'Savings account · same bank'}<input id="deposit-second" type="number" min="0" step="1000" value="${AU?40000:15000}" inputmode="decimal"></label></fieldset><button class="secondary">Check protection</button></form><div id="protection-result" aria-live="polite"></div><details><summary>What would ron do with this?</summary><ol><li>Flag the combined balance, with the source and check date.</li><li>Ask the adviser to verify account holder, eligibility, currency and banking licence.</li><li>Compare keeping the cash, spreading eligible deposits across separate licences or using it for an approved investment.</li><li>Get approval before moving anything. A protection alert never triggers a transfer by itself.</li></ol></details><p class="fine">${AU?'FCS: standard AU$250,000 per account holder per Australian-incorporated ADI, for eligible Australian-dollar deposits. Different brand names do not necessarily mean different ADIs.':'FSCS deposits: standard £120,000 per eligible depositor per authorised firm, from 1 December 2025. Joint accounts, eligibility and temporary high-balance protection need separate checks.'} Personal and company holders are assessed separately; their balances are not pooled simply because you own the company. This is deposit protection, not investment-loss insurance. <a href="${protectionSource}" target="_blank" rel="noopener">Official source ↗</a> · checked 17 October 2026.</p></section>`}
function updateProtection(){const a=Number($('#deposit-first').value),b=Number($('#deposit-second').value);if(!$('#deposit-first').value||!$('#deposit-second').value||!Number.isFinite(a)||!Number.isFinite(b)||a<0||b<0){$('#protection-result').textContent='Enter two balances of zero or more.';return}const [g]=depositCoverage([{holder:'personal',licence:'example-bank',balance:a},{holder:'personal',licence:'example-bank',balance:b}],protectionLimit);$('#protection-result').innerHTML=`<div class="protection-summary"><strong class="${g.outside?'exposure-number':'positive'}">${money(g.outside||g.headroom)}</strong><span>${g.outside?'above the standard deposit-protection limit':'remaining before the standard limit'}</span></div><div class="protection-bar" role="img" aria-label="${money(g.within)} within the standard limit; ${money(g.outside)} outside it"><i style="width:${g.total?Math.min(100,g.within/g.total*100):0}%"></i></div><div class="protection-key"><span>● ${money(g.within)} within limit</span><span>● ${money(g.outside)} above limit</span></div><p class="fine">${money(g.total)} combined · ${money(protectionLimit)} standard limit. Above-limit cash is not a forecast loss. Eligibility and any additional cover need professional confirmation.</p>`}
function limitsPage(){return `<p class="eyebrow">Know your position</p><h1>Limits & checks.</h1><p>What’s recorded. What’s left. What needs your adviser’s attention.</p><div class="limits-signposts"><a href="#tax">${AU?'Super caps & tax costs':'Tax allowances & costs'} →</a><a href="#rules">Rules & upcoming changes →</a></div><section><h2>${AU?'Super contributions':'Available tax headroom'}</h2><p class="fine">${AU?'2026/27 · recorded example contributions. Employer payments count too.':'2026/27 · recorded example use. Investments outside ron need reconciling.'}</p>${(AU?[['Concessional super',32500,18000],['Non-concessional super',130000,20000]]:[['ISA subscriptions',20000,8000],['EIS subscriptions · standard ceiling',1000000,20000],['CGT annual exempt amount',3000,1800]]).map(([n,total,used])=>`<div class="limit-chart"><div class="section-heading"><span>${n}</span><strong>${money(total-used)} left*</strong></div><div class="limit-bar"><i style="width:${used/total*100}%"></i></div><small>${money(used)} recorded / ${money(total)} standard limit</small></div>`).join('')}<p class="fine">*Recorded headroom is not permission or a recommendation to invest. ${AU?'Age, balances, employer contributions, existing bring-forward arrangements and carry-forward eligibility affect the actual amount.':'Eligibility, other subscriptions, income, connected interests and available tax liability affect relief. EIS subscription capacity is not tax-free cash.'} Your firm checks the facts before recommending action.</p></section>${protectionExample()}<section><h2>What needs checking?</h2><ul class="check-summary"><li>Any accounts, investments or contributions outside ron.</li><li>Who legally owns each account and which banking licence holds the deposits.</li><li>Spending reserves, upcoming tax and how long the money needs to stay accessible.</li><li>Changes in income, residence, employment or investment terms.</li></ul><a href="#journey/customer">See where this fits in the customer journey →</a></section>`}
window.ronScreens.limits=limitsPage;
const journeyDynamic=window.ronDynamic;window.ronDynamic=function(v){if(v.startsWith('journey/'))return flowPage(v.split('/')[1]);return journeyDynamic(v)};
tourStages.splice(1,0,{title:'Know the limits before moving cash',copy:'Recorded tax headroom is only a starting point. Check unrecorded contributions, eligibility and deposits sharing a banking licence. Try the cash-protection example.',route:'limits',role:false});
goTourStep=function(n){if(n>=tourStages.length){state.tourStep=null;persist();navigate('tour');return}state.tourStep=n;const t=tourStages[n];state.adviserMode=t.role;if(t.route==='invest/funding'){plan={type:'startup',eis:AU?'unknown':'yes',name:'Example Robotics',amount:200000,date:'2026-10-26',years:'5',cross:true,sales:true,route:'auto',cadence:'once',policy:'reinvest',offerPrice:10,valuation:10000000,valuationBasis:'post',previousValuation:8000000,terms:'preferred',annualGrowth:10,incomeYield:0,incomeRate:AU?47:35.75,receipt:'taxable',exitTarget:'personal'}}if(t.route==='client/alex')state.adviserPanel='plans';let route=t.route;if(route==='execution'){const r=state.requests.find(r=>r.stage==='Ready to execute')||state.requests.find(r=>r.stage);route=r?'plan/'+r.id:'plans'}persist();navigate(route)};
const journeyBind=bind;bind=function(){journeyBind();document.querySelectorAll('[data-start-journey]').forEach(b=>b.onclick=()=>goTourStep(b.dataset.startJourney==='firm'?3:0));document.querySelectorAll('[data-journey-role]').forEach(a=>a.onclick=()=>{state.adviserMode=a.dataset.journeyRole==='firm'||a.getAttribute('href').startsWith('#client/');state.tourStep=null;if(a.getAttribute('href').startsWith('#client/'))state.adviserPanel='plans';persist()});if($('#protection-form'))$('#protection-form').onsubmit=e=>{e.preventDefault();updateProtection()};if($('#demo-start'))$('#demo-start').onclick=()=>{state.tourStep=null;persist()};};
const journeyRender=render;render=function(){if(view()==='tour'){state.tourStep=null;persist()}journeyRender();const v=view(),root=$('#screen');if(v==='tour'||v.startsWith('journey/')){$('header nav').innerHTML=[['tour','Start'],['journey/customer','Customer'],['journey/firm','Firm']].map(([route,label])=>`<a href="#${route}" ${v===route?'aria-current="page"':''}>${label}</a>`).join('');$('header .mode-switch')?.remove()}$('header .logo').href='#tour';$('header .logo').setAttribute('aria-label','Ron demo start');if(v!=='tour'){root.insertAdjacentHTML('afterbegin',`<div class="demo-location"><a id="demo-start" href="#tour">← Demo start</a><span>${v.startsWith('journey/')?'How it works':state.adviserMode?'Firm view':'Customer view'} · ${AU?'AU':'UK'}</span></div>`)}if(['wealth','home'].includes(v)){const slot=$('#screen .invest-overview');if(slot)slot.insertAdjacentHTML('beforeend','<a class="limits-link" href="#limits">Check your limits & cash protection →</a>')}if(v==='tax')root.insertAdjacentHTML('beforeend','<p><a class="primary action-link" href="#limits">Cash protection & limits →</a></p>');if(v==='adviser')root.insertAdjacentHTML('afterbegin','<a class="workflow-link" href="#journey/firm">How the firm’s workflow works →</a>');if(v==='limits')updateProtection();bind()};render();
